import {esc, num, btn} from './visuals.mjs';
import {formatTime} from './model.mjs';
import {stamp, STAGES} from './safety-model.mjs';
import {icon} from './home.mjs';
import {deploymentSummary} from './work-zone.mjs';

const names={R1:'Worker safety',R2:'Queue warnings',R3:'Work-zone planning',R4:'Fleet & charging',SYSTEM:'Model data'};
const shortTitles={approach:'Vehicle approach',speed:'Vehicle speed alert',vehicle:'Restricted-zone entry',pedestrian:'Pedestrian intrusion',sos:'Worker SOS',rest:'Break requested','long-duty':'Extended duty',heart:'High heart rate',data:'Protection degraded',weather:'Weather advisory'};
export const eventTitle=e=>shortTitles[e.key]||e.title;
export function notificationStatus(e){
  if(e.type==='data')return {label:'No wearable notification',tone:'neutral',symbol:'−'};
  if(e.delivery==='failed')return {label:'Delivery failed',tone:'danger',symbol:'!'};
  if(e.delivery!=='delivered')return {label:'Delivery unconfirmed',tone:'warning',symbol:'?'};
  if(e.acknowledged)return {label:'Acknowledged',tone:'success',symbol:'✓'};
  return e.stage===3?{label:'No receipt recorded',tone:'neutral',symbol:'−'}:{label:'Awaiting acknowledgement',tone:'warning',symbol:'!'};
}
export function responseStatus(e){
  const labels=e.type==='support'?['Support requested','Support assigned','Support in progress','Support completed']:['Review required','Supervisor assigned','In progress','Closed'];
  return {label:labels[e.stage]||'Review required',tone:e.stage===3?'success':e.stage===0?(e.key==='sos'?'danger':'warning'):'info',symbol:e.stage===3?'✓':e.stage===0?'!':'↗'};
}
export function reportData(ws,options={}){
  const scope=options.scope||'all',sites=scope==='all'?ws.sites:ws.sites.filter(s=>s.id===options.siteId);
  const events=sites.flatMap(site=>site.events.map(e=>({...e,site,workerName:(site.roster||[site.worker]).find(w=>w.id===e.recipient)?.name||e.recipient}))).sort((a,b)=>b.created-a.created||b.id.localeCompare(a.id,undefined,{numeric:true}));
  const rows=events.filter(e=>(!options.eventType||options.eventType==='all'||e.type===options.eventType)&&(!options.response||options.response==='all'||(options.response==='open'?e.stage!==3:options.response==='unassigned'?e.stage===0:options.response==='closed'?e.stage===3:notificationStatus(e).label==='Awaiting acknowledgement'&&e.stage!==3)));
  return {sites,events,rows,selected:rows.find(e=>e.id===options.selectedId)||rows[0]||null,scopeLabel:scope==='all'?'All worksites':sites[0]?.name||'Selected worksite',metrics:{events:events.length,awaiting:events.filter(e=>e.type!=='data'&&e.delivery==='delivered'&&!e.acknowledged&&e.stage!==3).length,support:events.filter(e=>e.type==='support'&&e.stage!==3).length,relief:sites.reduce((n,s)=>n+(s.roster||[s.worker]).reduce((sum,w)=>sum+(w.breaks?.length||0),0),0)},unconfirmed:events.filter(e=>e.type!=='data'&&e.delivery!=='delivered'&&e.stage!==3).length,pending:sites.reduce((n,s)=>n+s.pending.length,0)};
}
const status=s=>`<span class="report-status ${s.tone}"><span class="report-status-icon" aria-hidden="true">${s.symbol}</span><span>${esc(s.label)}</span></span>`;
const select=(key,label,value,options)=>`<label class="report-filter"><span>${label}</span><select id="report-${key}" data-report-filter="${key}">${options.map(([id,text])=>`<option value="${id}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
function nextAction(e){
  if(e.stage===3)return 'Review the recorded outcome and retain the evidence.';
  if(e.type==='data')return 'Review equipment availability and the site backup procedure.';
  if(e.delivery!=='delivered')return 'Delivery is unconfirmed. Review local equipment and the backup alert procedure.';
  if(e.type==='support')return e.stage===0?'Assign a supervisor to this request.':e.stage===1?'Arrange assistance or relief for this worker.':'Confirm the handover when support is complete.';
  if(!e.acknowledged)return "Check the worker’s response. A receipt does not clear the hazard.";
  return e.stage===0?'Assign a supervisor to review the event.':e.condition?'The trigger is still active. Follow the site response procedure.':'Review the cleared trigger and record the outcome.';
}
function selectedEvent(e){
  if(!e)return `<aside class="report-detail report-detail-empty" id="report-selected" aria-labelledby="report-selected-title"><span class="report-kicker">SELECTED EVENT</span>${icon('report')}<h2 id="report-selected-title">Your event details appear here.</h2><p>Select an event to review notification delivery, acknowledgement and response history.</p></aside>`;
  const since=e.lastNotifiedAt??e.created,audit=e.audit||[],ack=audit.find(a=>a.at>=since&&a.acknowledged),deliveryLabel=e.type==='data'?'No wearable notification':e.delivery==='delivered'?'Watch alert delivered':e.delivery==='failed'?'Watch delivery failed':'Watch delivery unconfirmed';
  return `<aside class="report-detail" id="report-selected" aria-labelledby="report-selected-title"><span class="report-kicker">SELECTED EVENT</span><h2 id="report-selected-title">${esc(eventTitle(e))}</h2><p class="report-person"><strong>${esc(e.workerName)}</strong> · ${esc(e.site.name)}</p><p class="report-caption">${esc(e.recipient)} · ${esc(e.id)} · Simulated event</p><ol class="report-timeline"><li class="recorded"><time>${stamp(e.created)}</time><div><strong>${e.type==='hazard'?'Hazard detected':e.type==='support'?'Support request recorded':e.type==='data'?'Equipment issue recorded':'Advisory recorded'}</strong><p>${esc(e.title)}</p></div></li><li class="${e.delivery==='delivered'&&e.type!=='data'?'recorded':'unconfirmed'}"><time>${e.type==='data'?'—':stamp(since)}</time><div><strong>${deliveryLabel}</strong><p>${e.type==='data'?'This is a local equipment-status event.':e.delivery==='delivered'?'Simulated alert sent to the assigned worker.':'Receipt cannot be assumed. Check the response workflow.'}</p></div></li>${e.type==='data'?'':`<li class="${e.acknowledged?'recorded':'pending'}"><time>${e.acknowledged&&ack?stamp(ack.at):'—'}</time><div><strong>${e.acknowledged?'Acknowledgement received':e.stage===3?'No acknowledgement recorded':'Acknowledgement pending'}</strong><p>${e.acknowledged?'Worker receipt is recorded separately from the response.':'No worker receipt is recorded for this notification.'}</p></div></li>`}</ol><div class="report-response"><span>Response</span>${status(responseStatus(e))}<p>Owner: <strong>${esc(e.owner||'Unassigned')}</strong></p>${e.type==='hazard'?`<p>Trigger: <strong>${e.condition?'Active':'No longer observed'}</strong></p>`:''}${e.result?`<p>${esc(e.result)}</p>`:''}</div><div class="report-next"><h3>Next action</h3><p>${esc(nextAction(e))}</p>${btn(e.stage===3?'Open worksite ↗':'Open response ↗','worker-event','primary',`data-site="${esc(e.site.id)}" data-kind="${esc(e.type)}" data-worker="${esc(e.recipient)}"`)}<p class="report-receipt-note">ⓘ Acknowledgement confirms receipt, not hazard clearance.</p></div><details class="report-audit"><summary>Trigger & history <span>${audit.length} ${audit.length===1?'record':'records'}</span></summary><p>${esc(e.originalBasis||e.basis)}</p><p>Source: ${esc(e.source)}<br>Configuration v${e.configVersion}</p><ol>${audit.map(a=>`<li><time>${stamp(a.at)}</time><strong>${STAGES[a.stage]}</strong><p>${esc(a.owner||'Unassigned')} · ${esc(a.delivery||'unknown')} · ${a.acknowledged?'Acknowledged':'Not acknowledged'}${a.result?' · '+esc(a.result):''}</p></li>`).join('')}</ol></details>${!e.site.online?'<p class="report-sync-warning">Offline worksite: the supervisor copy may be stale. This panel shows the local record.</p>':''}</aside>`;
}
function supportingTools(s){
  const deployed=deploymentSummary();
  const planningDetail=deployed?`${deployed.plan} selected · ${deployed.details.delayMin} min mock delay · ${deployed.details.safety} safety risk`:`No deployment selected · build and compare a work-zone scenario`;
  const tools=[['queue','car','Queue warnings',`${s.feed?num(s.queue.length)+' m modelled queue':'Queue unavailable'} · ${s.queue.speed==null?'No virtual speed command':s.queue.speed+' km/h virtual speed'}`],['planning','pin','Work-zone planning',planningDetail],['fleet','sites','Fleet & charging',s.fleet.feasible?'Dispatch feasible under model assumptions':'Dispatch review required']];
  return `<section class="report-tools" aria-labelledby="report-tools-title"><div class="report-section-head"><h2 id="report-tools-title">Supporting tools</h2><p>Illustrative Cremorne model · separate from worker events</p></div>${tools.map(([id,ico,title,detail])=>`<div class="report-tool-row">${icon(ico)}<strong>${title}</strong><p>${esc(detail)}</p>${btn('Open ↗',`tool-${id}`,'report-text-button',`aria-label="Open ${title}"`)}</div>`).join('')}</section>`;
}
export function evidencePage(s,st,ws,government,options={}){
  const data=reportData(ws,options),{events,rows,selected,metrics,scopeLabel}=data;
  const metric=(label,value,detail)=>`<div><dt>${label}</dt><dd>${value}</dd><small>${detail}</small></div>`;
  return `<section class="report-page" aria-label="Evidence and report"><header class="report-heading"><div><div class="report-title-line"><h1>Evidence & report</h1><span class="report-session"><strong>SIMULATED SESSION</strong><span>Local session records</span></span></div><p>Worker events, notification receipts and follow-up.</p></div><div class="report-export"><div class="actions">${btn('Export report ↓','export','primary')}${btn('JSON','export','report-text-button')}${btn('CSV','csv','report-text-button')}${btn('Print','print','report-text-button')}</div><small>JSON / CSV include all worksites, regardless of filters.</small></div></header><dl class="report-metrics" aria-label="Summary for ${esc(scopeLabel)}">${metric('Worker events',metrics.events,esc(scopeLabel))}${metric('Awaiting acknowledgement',metrics.awaiting,'Delivered · open events')}${metric('Support requests',metrics.support,'Open requests')}${metric('Relief completed',metrics.relief,'Recorded handovers / breaks')}</dl>${data.unconfirmed||data.pending?`<div class="report-attention" role="status">${data.unconfirmed?`<strong>${data.unconfirmed} notification${data.unconfirmed===1?'':'s'} unconfirmed.</strong> Check delivery status in the event history. `:''}${data.pending?`${data.pending} local update${data.pending===1?'':'s'} awaiting cloud sync; the supervisor copy may be stale.`:''}</div>`:''}<div class="report-grid"><section class="report-ledger" aria-labelledby="report-ledger-title"><div class="report-section-head"><div><h2 id="report-ledger-title">Worker event history</h2><p>${esc(scopeLabel)} · ${rows.length} of ${events.length} events</p></div><div class="report-filters">${select('scope','Worksites',options.scope||'all',[['selected','Selected worksite'],['all','All worksites']])}${select('eventType','Event type',options.eventType||'all',[['all','All events'],['hazard','Hazards'],['support','Worker support'],['weather','Weather'],['data','Equipment status']])}${select('response','Response',options.response||'all',[['all','All responses'],['open','Open events'],['unassigned','Unassigned'],['pending','Awaiting acknowledgement'],['closed','Completed / closed']])}</div></div><div class="report-table-scroll" role="region" aria-label="Worker event records" tabindex="0"><table class="report-table"><thead><tr><th scope="col">Time</th><th scope="col">Worker / event</th><th scope="col">Notification</th><th scope="col">Response</th></tr></thead><tbody>${rows.map(e=>`<tr class="${selected?.id===e.id?'is-selected':''}" data-action="report-select" data-id="${esc(e.id)}"><td><time>${stamp(e.created)}</time><small>${esc(e.site.name)}</small></td><td><button class="report-event-trigger" data-action="report-select" data-id="${esc(e.id)}" aria-pressed="${selected?.id===e.id}" aria-controls="report-selected" aria-label="Review ${esc(eventTitle(e))} for ${esc(e.workerName)}"><strong>${esc(e.workerName)}</strong><span>${esc(eventTitle(e))}</span></button><small>${esc(e.recipient)}</small></td><td>${status(notificationStatus(e))}</td><td>${status(responseStatus(e))}<small>${esc(e.owner||'Unassigned')}</small></td></tr>`).join('')}</tbody></table>${!rows.length?`<div class="report-empty">${icon(events.length?'report':'shield')}<h3>${events.length?'No events match these filters.':'No worker events recorded yet.'}</h3><p>${events.length?'Change the filters to review the other events in this scope.':'Start a simulated scenario to follow notification delivery and the response here.'}</p><div class="actions">${events.length?btn('Clear event filters','report-reset'):btn('Try worker SOS','demo-sos','primary')+btn('Play vehicle approach','demo-vehicle')}</div></div>`:''}</div></section>${selectedEvent(selected)}${supportingTools(s)}</div><details class="report-model-history"><summary>Supporting model event history <span>${st.history.length} records · Cremorne example</span></summary><p>Separate from worker safety notifications. Model time is independent of the worker replay.</p><div class="report-table-scroll"><table><thead><tr><th>Model time</th><th>Function</th><th>Event</th><th>Receipt</th><th>Evidence</th></tr></thead><tbody>${st.history.length?st.history.slice().reverse().map(e=>`<tr><td>${formatTime(480+e.time/60)}</td><td>${names[e.module]||esc(e.module)}</td><td>${esc(e.title)}</td><td>${st.acknowledged.includes(e.id)?'Acknowledged':'Not acknowledged'}</td><td>${btn('Inspect','inspect','small',`data-id="${esc(e.id)}"`)}</td></tr>`).join(''):'<tr><td colspan="5">No supporting model events recorded.</td></tr>'}</tbody></table></div></details><footer class="report-provenance"><strong>Data sources & provenance</strong><span>SCATS historical counts · Vicmap road geometry</span><span>Operational events, workers and devices are simulated.</span>${btn('View sources →','report-sources','report-text-button')}</footer><details class="report-source-details" id="report-sources"><summary>Source details & report guidance</summary><div><p>SCATS historical detector counts and Vicmap road geometry provide road context. They do not measure the hazards, heart rate, weather or queues in this demonstration.</p><p>${government?.scats?'Official-data snapshots are included in the scenario export.':'See source availability in Worker safety → Site layout → Official road context.'} Review the selected junction, source date, attribution and refresh status in Site layout. Richmond and Southbank have no supporting queue, planning or fleet models.</p><p>JSON includes all worksites, configurations, complete worker event audits, official-data provenance, both plan comparisons and supporting snapshots. CSV includes all worker and supporting model events. Print captures the current report view. Records last for this page session; export before reloading.</p><p>Acknowledgement confirms receipt. Closure requires the corresponding response steps. A feasible fleet plan does not establish site readiness. No physical wearable, camera or road sign is connected.</p><a href="./operating-guide.html" target="_blank" rel="noopener">Read the operating guide ↗</a></div></details></section>`;
}
